/**
 * The Winepress
 * -------------
 * Gideon threshes wheat in a winepress to hide it from Midian, and the angel of the Lord appears under the oak at Ophrah. Stage: a hidden winepress in a vineyard at dawn, a man beating wheat, a figure in shining raiment beneath the oak; dust, shadow, and the first gleam of the divine messenger.
 *
 * Palette 0x2a1a10 → 0x0a0502 · light: dawn · hero: tree
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, oak, wheat, vineyard, person, birds } from './gideon-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 3030479649, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0a0502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* trees: broadleaf shade */
    oak(W, group, -28.6, 0, -42.4, 1.13, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -12.4, 0, -45.9, 1.05, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 27.9, 0, -22.2, 1.05, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 43.5, 0, -26.7, 1.37, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 52.7, 0, -52.6, 0.99, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x2e1d12, head: 0x352114 });
    /* vineyard: posts, canopies, hanging fruit */
    vineyard(W, group, 0, 30, 40, 80, { leaf: 0x4f8a2e, berry: 0x1d120b });

    /* hero: the great tree */
    oak(W, group, 0, 0, 0, 1.7, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    W.disc([0, 8, -16], 9, 0x372215, 0.25);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2a1a10, ry: -0.59, s: 1.19 });

    /* birds: slow circles high above */
    birds(W, group, 6, 55, { y: 26 });

    return W.finish();
}

export default { build };
